t.script:

document.addEventListener('DOMContentLoaded', function() {
  function renderFullCart() {
    const cart = JSON.parse(localStorage.getItem('cart') || '[]');
    const container = document.getElementById('cart-items-list');
    const totalItems = document.getElementById('cart-total-items');
    const subtotalEl = document.getElementById('summary-subtotal');
    const totalEl = document.getElementById('summary-total');

    let html = '';
    let subtotal = 0;

    if (cart.length === 0) {
      html = `
        <div class="text-center py-5">
          <p class="display-6 text-muted mb-4">Your cart is empty</p>
          <a href="/tenStore" class="btn btn-dark px-5 py-3">Continue Shopping</a>
        </div>`;
      totalItems.textContent = '0';
    } else {
      totalItems.textContent = cart.reduce((s, i) => s + i.qty, 0);
      cart.forEach((item, index) => {
        subtotal += item.price * item.qty;
        html += `
          <div class="border rounded p-4 mb-4 bg-white shadow-sm">
            <div class="row g-3 align-items-start">
              <div class="col-3">
                <img src="${item.image}" alt="${item.name}" class="img-fluid rounded" style="height:120px; object-fit:cover;">
              </div>
              <div class="col-6">
                <h5 class="mb-2">${item.name}</h5>
                <p class="text-muted small mb-2">Ten Wellness</p>
                <p class="fw-bold mb-0">${item.price.toFixed(2)} KWD</p>
              </div>
              <div class="col-3 text-end">
                <div class="d-flex align-items-center justify-content-end gap-2 mb-3">
                  <button onclick="window.updateQty(${index}, -1)"
                          class="btn btn-sm btn-outline-dark rounded-circle" style="width:36px; height:36px;">-</button>
                  <span class="mx-3 fw-bold">${item.qty}</span>
                  <button onclick="window.updateQty(${index}, 1)"
                          class="btn btn-sm btn-outline-dark rounded-circle" style="width:36px; height:36px;">+</button>
                </div>
                <button onclick="window.removeFromCart(${index})"
                        class="btn btn-link text-danger small p-0">Remove</button>
              </div>
            </div>
          </div>`;
      });
    }

    container.innerHTML = html;
    subtotalEl.textContent = subtotal.toFixed(2) + ' KWD';
    totalEl.textContent = subtotal.toFixed(2) + ' KWD';
  }

  // Global functions for buttons
  window.updateQty = function(index, change) {
    let cart = JSON.parse(localStorage.getItem('cart') || '[]');
    cart[index].qty += change;
    if (cart[index].qty <= 0) cart.splice(index, 1);
    localStorage.setItem('cart', JSON.stringify(cart));
    window.updateCartCount?.();
    renderFullCart();
  };

  window.removeFromCart = function(index) {
    let cart = JSON.parse(localStorage.getItem('cart') || '[]');
    cart.splice(index, 1);
    localStorage.setItem('cart', JSON.stringify(cart));
    window.updateCartCount?.();
    renderFullCart();
  };

  renderFullCart();
});
